<script lang="ts">
 import '../styles/product-refresh.css';
 import { Heart, Minus, Plus, Truck, RotateCcw, Ruler, ArrowRight } from 'lucide-svelte'; import { products, money, colorHex } from '../lib/data/products'; import { addToCart, wishlist, toggleWishlist, notify } from '../lib/stores/commerce'; import ProductCard from '../lib/components/ProductCard.svelte';
 let { id }: {id: string} = $props(); let product = $derived(products.find(p=>p.id===id)); let selectedSize = $state(''); let quantity = $state(1); let error = $state(''); let sizeDialog = $state<HTMLDialogElement>();
 const zoomSteps=[1,1.5,2,2.5,3,4,5,6,8,10];
 let zoomLevel=$state(1),zoomX=$state(50),zoomY=$state(50);
 let pointerStart:{x:number;y:number}|null=null,dragged=false;
 let isPanning=$state(false);
 const activePointers=new Map<number,{x:number;y:number}>();
 let pinchStartDistance=0,pinchStartZoom=1;
 function changeZoom(direction:number){const next=direction>0?zoomSteps.find(step=>step>zoomLevel+.01):[...zoomSteps].reverse().find(step=>step<zoomLevel-.01);if(next!==undefined)zoomLevel=next;if(zoomLevel===1){zoomX=50;zoomY=50;}}
 function pointerDown(event:PointerEvent){if(event.pointerType==='mouse'&&event.button!==0)return;if(zoomLevel>1){event.preventDefault();isPanning=true;}activePointers.set(event.pointerId,{x:event.clientX,y:event.clientY});(event.currentTarget as HTMLElement).setPointerCapture(event.pointerId);pointerStart={x:event.clientX,y:event.clientY};dragged=false;if(activePointers.size===2){const [a,b]=[...activePointers.values()];pinchStartDistance=Math.hypot(a.x-b.x,a.y-b.y);pinchStartZoom=zoomLevel;dragged=true;}}
 const clampOrigin=(value:number)=>Math.max(0,Math.min(100,value));
 function moveZoom(event:PointerEvent){
  const previous=activePointers.get(event.pointerId);
  const previousPair=activePointers.size===2?[...activePointers.values()]:null;
  if(activePointers.has(event.pointerId))activePointers.set(event.pointerId,{x:event.clientX,y:event.clientY});
  const rect=(event.currentTarget as HTMLElement).getBoundingClientRect();
  if(activePointers.size===2&&pinchStartDistance>0&&previousPair){
   const [a,b]=[...activePointers.values()];
   const [oldA,oldB]=previousPair;
   const nextZoom=Math.max(1,Math.min(10,Math.round(pinchStartZoom*Math.hypot(a.x-b.x,a.y-b.y)/pinchStartDistance*10)/10));
   const ratio=nextZoom/zoomLevel;
   const oldMidX=(oldA.x+oldB.x)/2-rect.left,oldMidY=(oldA.y+oldB.y)/2-rect.top;
   const newMidX=(a.x+b.x)/2-rect.left,newMidY=(a.y+b.y)/2-rect.top;
   if(nextZoom>1){
    const oldTranslateX=(1-zoomLevel)*zoomX/100*rect.width;
    const oldTranslateY=(1-zoomLevel)*zoomY/100*rect.height;
    zoomX=clampOrigin((newMidX-ratio*(oldMidX-oldTranslateX))/(1-nextZoom)/rect.width*100);
    zoomY=clampOrigin((newMidY-ratio*(oldMidY-oldTranslateY))/(1-nextZoom)/rect.height*100);
   }else{zoomX=50;zoomY=50;}
   zoomLevel=nextZoom;
   dragged=true;
   return;
  }
  if(zoomLevel===1||!previous||(event.pointerType!=='mouse'&&!activePointers.has(event.pointerId)))return;
  // CSS translation is (1 - scale) * origin. Subtracting the movement from
  // the origin makes the enlarged image follow the pointer, instead of reverse.
  zoomX=clampOrigin(zoomX-(event.clientX-previous.x)/rect.width*100/(zoomLevel-1));
  zoomY=clampOrigin(zoomY-(event.clientY-previous.y)/rect.height*100/(zoomLevel-1));
  if(pointerStart&&Math.hypot(event.clientX-pointerStart.x,event.clientY-pointerStart.y)>6)dragged=true;
 }
 function pointerEnd(event:PointerEvent){activePointers.delete(event.pointerId);isPanning=activePointers.size>0&&zoomLevel>1;pointerStart=null;if(activePointers.size<2)pinchStartDistance=0;}
 function wheelZoom(node:HTMLElement){let lastWheel=0;const handle=(event:WheelEvent)=>{if(event.ctrlKey||event.metaKey)return;event.preventDefault();const direction=event.deltaY<0?1:-1;if((direction>0&&zoomLevel===10)||(direction<0&&zoomLevel===1))return;const now=Date.now();if(now-lastWheel<70)return;lastWheel=now;const rect=node.getBoundingClientRect();zoomX=Math.max(0,Math.min(100,(event.clientX-rect.left)/rect.width*100));zoomY=Math.max(0,Math.min(100,(event.clientY-rect.top)/rect.height*100));changeZoom(direction);};node.addEventListener('wheel',handle,{passive:false});return{destroy(){node.removeEventListener('wheel',handle);}};}
 function clickZoom(){if(dragged){dragged=false;return;}if(zoomLevel===10){zoomLevel=1;zoomX=50;zoomY=50;}else changeZoom(1);}
 $effect(()=>{id;isPanning=false;activePointers.clear();selectedSize='';quantity=1;error='';zoomLevel=1;zoomX=50;zoomY=50;});
 function add(){if(!product)return;if(!selectedSize){error='Please choose your size before adding to your bag.';return;}addToCart(product.id,selectedSize,product.color,quantity);error='';notify('Added to your bag');}
</script>
{#if product}<div class="breadcrumbs content-width"><a href="#/">Home</a><span>/</span><a href="#/shop">Collection</a><span>/</span><span>{product.name}</span></div><section class="product-detail product-editorial"><div class="product-gallery"><button class="main-product-image" use:wheelZoom class:zoomed={zoomLevel>1} class:panning={isPanning} style={`--zoom-level:${zoomLevel};--zoom-x:${zoomX}%;--zoom-y:${zoomY}%`} onclick={clickZoom} ondragstart={(event)=>event.preventDefault()} onpointerdown={pointerDown} onpointermove={moveZoom} onpointerup={pointerEnd} onpointercancel={pointerEnd} aria-label={zoomLevel===10?'Product image at 10 times zoom. Click to reset.':`Product image at ${zoomLevel} times zoom. Click to zoom in.`}><img draggable="false" src={product.image} alt={`${product.name}, full garment display without a model`}/><span>{zoomLevel===1?'Click, scroll or pinch to zoom +':`Zoom ${zoomLevel}× · Move, drag, scroll or pinch to inspect`}</span></button><div class="image-zoom-controls" aria-label="Product image zoom controls"><button type="button" onclick={()=>changeZoom(-1)} disabled={zoomLevel===1} aria-label="Zoom out"><Minus size={16}/></button><output aria-live="polite" aria-label="Current zoom">{zoomLevel}×</output><button type="button" onclick={()=>changeZoom(1)} disabled={zoomLevel===10} aria-label="Zoom in"><Plus size={16}/></button><button type="button" class="zoom-reset" onclick={()=>{zoomLevel=1;zoomX=50;zoomY=50;}} disabled={zoomLevel===1}>Reset</button></div><div class="gallery-note">PRODUCT-ONLY DISPLAY · ILLUSTRATIVE DEMO IMAGE</div></div><div class="product-info"><span class="eyebrow">{product.category} · THE RAQVOI EDIT</span><h1>{product.name}</h1><div class="detail-price"><strong>{money(product.price)}</strong>{#if product.originalPrice}<s>{money(product.originalPrice)}</s><span>Save {money(product.originalPrice-product.price)}</span>{/if}</div><p class="tax-note">Demo price in INR · no payment will be collected</p><p class="product-description">{product.description}</p><div class="selection-label">Colour <strong>{product.color}</strong></div><div class="product-colour"><span style={`background:${colorHex[product.color]}`}></span><small>Shown in {product.color}</small></div><div class="selection-label">Select size <button class="inline-button" onclick={()=>sizeDialog?.showModal()}><Ruler size={14}/> Size guide</button></div><div class="size-selector">{#each product.sizes as s}<button class:selected={selectedSize===s} aria-pressed={selectedSize===s} onclick={()=>{selectedSize=s;error='';}}>{s}</button>{/each}</div>{#if error}<p class="form-error" role="alert">{error}</p>{/if}<div class="product-purchase"><div class="quantity-control"><button aria-label="Decrease quantity" onclick={()=>quantity=Math.max(1,quantity-1)} disabled={quantity<=1}><Minus size={14}/></button><span>{quantity}</span><button aria-label="Increase quantity" onclick={()=>quantity=Math.min(10,quantity+1)} disabled={quantity>=10}><Plus size={14}/></button></div><button class="button dark add-to-bag" onclick={add}>Add to bag <ArrowRight size={17}/></button><button class="outline-heart" class:hearted={$wishlist.includes(product.id)} aria-label="Save product to wishlist" aria-pressed={$wishlist.includes(product.id)} onclick={()=>toggleWishlist(product!.id)}><Heart size={20} fill={$wishlist.includes(product.id)?'currentColor':'none'}/></button></div><div class="product-perks"><span><Truck size={17}/>Free demo delivery over ₹3,500</span><span><RotateCcw size={17}/>Explore sizing before you choose</span></div><details><summary>The details</summary><p>Sample fabric specification: {product.fabric}.</p><ul>{#each product.details as detail}<li>{detail}</li>{/each}</ul></details><details><summary>Care & fit</summary><p>Demo care guidance: gentle hand wash with like colours, dry in shade, and iron on low heat. Final care labels will be confirmed when real products are added.</p><p>Check the illustrative size guide before choosing. Measurements are in centimetres.</p></details><details><summary>Delivery & returns</summary><p>This static store is a demonstration. No order is fulfilled or shipped. Demo shipping is ₹99 below ₹3,500 and free at ₹3,500 and above, based on the bag subtotal before coupons.</p><a class="text-link" href="#/help">Read demo policies ↗</a></details></div></section><section class="section soft-section"><div class="section-heading"><div><span class="eyebrow">CONTINUE YOUR STORY</span><h2>You may also love.</h2></div></div><div class="product-grid home-products">{#each products.filter(p=>p.id!==id).slice(0,4) as related}<ProductCard product={related}/>{/each}</div></section><dialog class="size-dialog" bind:this={sizeDialog}><div class="dialog-heading"><h2>Find your fit.</h2><button onclick={()=>sizeDialog?.close()} aria-label="Close size guide">×</button></div><p>Illustrative garment guide · centimetres</p><table><thead><tr><th>Size</th><th>Bust</th><th>Waist</th><th>Hip</th></tr></thead><tbody>{#each [['XS',82,66,90],['S',87,71,95],['M',92,76,100],['L',97,81,105],['XL',102,86,110],['XXL',107,91,115]] as row}<tr>{#each row as value}<td>{value}</td>{/each}</tr>{/each}</tbody></table><p>Measure around the fullest part of your bust and hips. These sample measurements are for exploring the demo.</p></dialog>{:else}<section class="empty-state"><h1>This piece couldn’t be found.</h1><a href="#/shop" class="button dark">Back to the collection</a></section>{/if}

